import { useState } from 'react';

export default function {{component_name}}({ max = 5 }: { max?: number }) {
  const [rating, setRating] = useState(0);
  return (
    <div>
      {Array.from({ length: max }).map((_, i) => (
        <button key={i} onClick={() => setRating(i + 1)} className="text-2xl">
          {i < rating ? '★' : '☆'}
        </button>
      ))}
    </div>
  );
}
